files.model.cfdl:
version 0.1
model "exercise-rent-increase"
time calendar monthly from 2026-01 for 24

entity asset workshop : Asset.Real

// The workshop rents for 4,200 a month for two years. Your task: the
// landlord raises the rent 5% for the second year. Express that as claims —
// split this stream into a year-one stream and a year-two stream at the
// higher amount.
stream workshop.rent on entity asset.workshop inflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 4200
}

stream workshop.operating_cost on entity asset.workshop outflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 900
}

01-why-a-language/rent-increase.solution:
version 0.1
model "exercise-rent-increase"
time calendar monthly from 2026-01 for 24

entity asset workshop : Asset.Real

// Year one at the original rent.
stream workshop.rent_y1 on entity asset.workshop inflow currency USD {
  schedule every month from 2026-01 to 2026-12
  amount = 4200
}

// Year two at 5% more. Writing 4200 * 1.05 rather than 4410 keeps the claim
// legible: the reader sees the base and the increase, not just the result.
stream workshop.rent_y2 on entity asset.workshop inflow currency USD {
  schedule every month from 2027-01 to 2027-12
  amount = 4200 * 1.05
}

stream workshop.operating_cost on entity asset.workshop outflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 900
}

files.model.cfdl:
version 0.1
model "exercise-studio-setup"
time calendar monthly from 2026-01 for 24

// Your task, in three steps:
//   1. Declare the studio as an entity (a real asset).
//   2. Add a fitout phase covering the first two months.
//   3. Add two streams: a monthly rent cost of 1,850 for the full two years,
//      and a one-time 12,000 setup cost that lands when fitout begins —
//      schedule it with phase_enter, not a date.

02-the-object-model/studio-setup.solution:
version 0.1
model "exercise-studio-setup"
time calendar monthly from 2026-01 for 24
phase fitout from 2026-01 to 2026-02

entity asset studio : Asset.Real

// The setup cost is tied to the phase, not a date: slide the fitout phase
// and the cash follows without this stream changing.
stream studio.setup_cost on entity asset.studio outflow currency USD {
  schedule on phase_enter("fitout")
  amount = 12000
}

stream studio.rent on entity asset.studio outflow currency USD {
  schedule every month from 2026-01 to 2027-12
  amount = 1850
}

